discrepancies as (
  select
    'solo_en_respaldo'::text as discrepancy_type,
    b.case_id::text as case_id,
    to_jsonb(b) as record_data
  from neuroguia_respaldo_20260725_001622.ng_case_memory b
  where not exists (
    select 1
    from canonical_case_ids c
    where c.case_id = b.case_id::text
  )

  union all

  select
    'solo_en_paquete'::text as discrepancy_type,
    c.case_id,
    null::jsonb as record_data
  from canonical_case_ids c
  where not exists (
    select 1
    from neuroguia_respaldo_20260725_001622.ng_case_memory b
    where b.case_id::text = c.case_id
  )
)
select
  discrepancy_type,
  case_id,
  count(*) filter (
    where discrepancy_type = 'solo_en_respaldo'
  ) over () as cases_only_in_backup,
  count(*) filter (
    where discrepancy_type = 'solo_en_paquete'
  ) over () as cases_only_in_package,
  record_data
from discrepancies
order by discrepancy_type, case_id;
